// Cartellino esclusione 2 minuti integrato nel progetto Referto Pallamano.
// Stampa su un unico A4 due cartellini: quello superiore capovolto di 180°
// e quello inferiore nel verso normale. Il colore usa quello configurato per la squadra.
window.stampaCartellinoEsclusione = function(dati) {
  try {
    const squadra = String(dati?.squadra ?? '').trim();
    const numero = String(dati?.numero ?? '').trim();
    const rientro = String(dati?.tempoRientro ?? '').trim();
    const colore = String(dati?.colore ?? '#2563EB').trim() || '#2563EB';

    const ticket = (rotated) => `
      <div class="ticket ${rotated ? 'rotated' : ''}" style="--team-color:${colore}">
        <div class="circle">${squadra}/${numero}</div>
        <div class="logo"><img src="data:image/png;base64,"></div>
        <div class="time">${rientro}</div>
      </div>`;

    const html = `<!DOCTYPE html>
<html lang="it"><head><meta charset="UTF-8"><title>Esclusione 2 Minuti</title>
<style>
@page{size:A4;margin:0}
*{box-sizing:border-box}
html,body{margin:0;padding:0;background:#fff;font-family:Arial,sans-serif}
.page{width:210mm;height:297mm;background:#fff;margin:0 auto;padding:7mm 8mm}
.ticket{position:relative;height:132mm;border:2px solid #111;overflow:hidden;transform-origin:center center}
.ticket.rotated{transform:rotate(180deg)}
.sep{height:1px;border-top:1px dashed #555;margin:4mm 0}
.circle{position:absolute;left:10mm;top:10mm;width:95mm;height:95mm;border:2px solid var(--team-color);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:82px;font-weight:700;color:var(--team-color);line-height:1;white-space:nowrap}
.time{position:absolute;right:8mm;bottom:10mm;width:90mm;height:32mm;border:2px solid var(--team-color);display:flex;align-items:center;justify-content:center;font-size:62px;font-weight:700;color:var(--team-color);line-height:1;white-space:nowrap}
.logo{position:absolute;right:18mm;top:18mm;width:35mm;height:52mm;display:flex;align-items:center;justify-content:center}
.logo img{width:auto;height:52mm;display:block}
@media print{html,body{background:#fff}.page{margin:0}}
</style></head>
<body>
<div class="page">
  ${ticket(true)}
  <div class="sep"></div>
  ${ticket(false)}
</div>
</body></html>`;

    const w = window.open('', '_blank', 'width=900,height=1200');
    if (!w) {
      alert('Impossibile aprire la stampa del cartellino. Consenti le finestre popup per il referto.');
      return;
    }
    w.document.open();
    w.document.write(html);
    w.document.close();
    w.focus();
    setTimeout(() => {
      w.print();
      w.onafterprint = () => { try { w.close(); } catch(e) {} };
      setTimeout(() => { try { w.close(); } catch(e) {} }, 1200);
    }, 350);
  } catch(e) {
    console.error('Errore stampa cartellino:', e);
  }
};
